import { useState, type ReactNode } from 'react';
import { createPortal } from 'react-dom';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { experimentOutput, experimentRunIds, experimentSampleStages, type EvalExperiment } from '../../../../domain/mapping/evals/experiment';
import type { EvalRunCell, EvalRunPrompt, EvalRunSummary } from '../../../../domain/mapping/evals/evalRun';
import type { ExperimentRoute } from './ExperimentExplorer';
import { Drawer } from './Drawer';
import { statusLabel } from './evalsFormat';

type Node = { id: string; label: ReactNode; children?: Node[]; collapsed?: boolean };
type Row = { sample: EvalExperiment['samples'][number]; stage: EvalExperiment['workflow']['stages'][number]; output?: EvalExperiment['samples'][number]['outputs'][number]; run?: EvalRunSummary; cell?: EvalRunCell };

function Branch({ node, prefix = '', last = true }: { node: Node; prefix?: string; last?: boolean }) {
  const [open, setOpen] = useState(!node.collapsed);
  return <li>
    <div className="experiment-ascii-row">
      <span className="experiment-ascii-guide" aria-hidden="true">{prefix}{last ? '`-- ' : '+-- '}</span>
      <div className="experiment-ascii-content">
        {node.children?.length ? <button className="experiment-ascii-toggle" aria-label={`${open ? 'Collapse' : 'Expand'} ${node.id}`} aria-expanded={open} onClick={() => setOpen(!open)}>{open ? '[-]' : '[+]'}</button> : null}
        {node.label}
      </div>
    </div>
    {open && !!node.children?.length && <ul>{node.children.map((child, index) => <Branch key={child.id} node={child} prefix={prefix + (last ? '    ' : '|   ')} last={index === node.children!.length - 1} />)}</ul>}
  </li>;
}

function progress(rows: Row[]) {
  const done = rows.filter(row => row.cell?.status === 'finished' && !row.cell.deleted).length;
  const statuses = rows.map(row => row.cell?.status);
  const state = statuses.includes('generating') ? 'generating' : statuses.includes('queued') ? 'queued'
    : statuses.includes('failed') ? 'failed' : statuses.includes('cancelled') ? 'cancelled'
    : rows.length && done === rows.length ? 'finished' : 'planned';
  return <span className="experiment-ascii-status" data-status={state}>[{state === 'finished' ? 'done' : state} · {done}/{rows.length} outputs]</span>;
}

/** Agent-authored descriptions supply commentary; all counts, actions and statuses come from records. */
export function ExperimentOverview({ experiment, runs, phaseId, onOpen }: {
  experiment: EvalExperiment; runs: EvalRunSummary[]; phaseId?: string;
  onOpen: (route: ExperimentRoute | { kind: 'run'; id: string; output?: string }) => void;
}) {
  const [drawer, setDrawer] = useState<{ title: string; content: ReactNode }>();
  const related = [...new Set([...experimentRunIds(experiment), ...(experiment.generationReview?.runs ?? []).map(run => run.id)])].flatMap(id => runs.find(run => run.id === id) ?? experiment.generationReview?.runs.find(run => run.id === id) ?? []);
  const allRuns = [...runs, ...(experiment.generationReview?.runs ?? []).filter(run => !runs.some(saved => saved.id === run.id))];
  const rows: Row[] = experiment.samples.flatMap(sample => experimentSampleStages(experiment, sample).map(stage => {
    const planned = experiment.plannedRuns?.flatMap(run => run.outputs.filter(output => output.sampleId === sample.id && output.stageId === stage.id).map(output => ({ ...output, runId: run.request.requestId })))[0];
    const output = sample.outputs.find(output => output.stageId === stage.id) ?? planned;
    return { sample, stage, output, run: output && allRuns.find(run => run.id === output.runId), cell: output && experimentOutput(output, allRuns) };
  }));
  const inspect = (title: string, value: unknown) => setDrawer({ title, content: <pre className="experiment-inspect-json">{JSON.stringify(value, null, 2)}</pre> });
  const action = (label: string, onClick: () => void, title?: string) => <button type="button" className="evals-link experiment-ascii-action" title={title} onClick={onClick}>[{label}]</button>;
  const prompt = (pinned: EvalRunPrompt, stage: string) => setDrawer({ title: `${pinned.name} · v${pinned.version ?? '?'} · ${stage}`, content: <>
    <p className="evals-muted">Pinned stage prompt, displayed as Markdown. Template variables, where present, are shown as saved.</p>
    <div className="experiment-rendered-prompt"><ReactMarkdown remarkPlugins={[remarkGfm]}>{pinned.stages[stage]}</ReactMarkdown></div>
    <details><summary>Source text</summary><pre className="experiment-inspect-json">{pinned.stages[stage]}</pre></details>
    {!!Object.keys(pinned.references ?? {}).length && <details><summary>Pinned references</summary>{Object.entries(pinned.references!).map(([id, reference]) => <section key={id}><h4>{reference.name}</h4><pre>{reference.ascii}</pre>{reference.comment && <p>{reference.comment}</p>}</section>)}</details>}
  </> });
  const outputNode = (row: Row): Node => {
    const { sample, stage, output, cell, run } = row;
    const input = experiment.cases.find(item => item.id === sample.caseId)!;
    const condition = experiment.conditions.find(item => item.id === sample.conditionId)!;
    const pinned = run?.prompts.find(prompt => prompt.promptId === cell?.promptId && (!cell.promptVersion || prompt.version === cell.promptVersion));
    const scaffold = run?.workflow === 'diagram-history' && cell?.historyArtifact?.stepId.startsWith('scaffold-');
    const origin = scaffold ? rows.find(candidate => candidate.cell?.historyArtifact?.stepId === 'plan' && candidate.run?.prompts.some(prompt => prompt.promptId === pinned?.promptId && prompt.version === pinned?.version)) : undefined;
    const title = [experiment.cases.length > 1 ? `${input.id === 'sequence' ? '' : input.id + ' · '}${input.name}` : '', scaffold ? '' : run?.workflow === 'diagram-history' && stage.id === 'plan' ? 'Global plan' : stage.name,
      experiment.conditions.length > 1 ? condition.name : '', !scaffold && (run?.request.passes ?? 1) > 1 ? `sample ${sample.number}` : '', sample.attempt > 1 ? `attempt ${sample.attempt}` : ''].filter(Boolean).join(' · ');
    const count = cell?.output?.canvases.length;
    const children: Node[] = [];
    if (cell?.error) children.push({ id: `${sample.id}-${stage.id}-error`, label: <span className="evals-error">{cell.error}</span> });
    if (cell?.explanation) children.push({ id: `${sample.id}-${stage.id}-comment`, label: <span className="experiment-ascii-comment"># {cell.explanation}</span> });
    if (run?.historyInput) {
      const previous = rows.find(candidate => candidate.cell?.historyArtifact?.timelineId === run.historyInput!.timelineId && candidate.cell.historyArtifact.stepId === run.historyInput!.stepId);
      children.push({ id: `${sample.id}-${stage.id}-dependency`, label: <>Starts from {run.historyInput.stepId} {previous?.output && action('output', () => onOpen({ kind: 'run', id: previous.output!.runId, output: previous.output!.cellKey }))}</> });
    }
    return { id: `${sample.id}-${stage.id}`, collapsed: true, label: <>
      <span>{title}</span> <span className="experiment-ascii-status" data-status={cell?.status}>[{cell?.deleted ? 'unavailable' : cell ? statusLabel[cell.status].toLowerCase() : output ? 'unavailable' : 'planned'}{count !== undefined ? ` · ${count} canvas${count === 1 ? '' : 'es'}` : ''}]</span>
      {output && cell && action(cell.status === 'finished' ? 'output' : 'details', () => onOpen({ kind: 'run', id: output.runId, output: output.cellKey }))}
      {scaffold ? origin?.output && action('generation source', () => onOpen({ kind: 'run', id: origin.output!.runId, output: origin.output!.cellKey }))
        : pinned?.stages[stage.id] && action('prompt', () => prompt(pinned, stage.id))}
      {action('inputs', () => inspect(`${title} · pinned inputs`, { case: input, contexts: run?.contexts, canvases: run?.inputs, canvasSet: run?.canvasInputs, history: run?.historyInput, request: run?.request }))}
    </>, children };
  };
  const phaseOutputs = (phaseRows: Row[]): Node[] => {
    const scaffolds = phaseRows.filter(row => row.run?.workflow === 'diagram-history' && row.cell?.historyArtifact?.stepId.startsWith('scaffold-'));
    return [
      ...phaseRows.filter(row => !scaffolds.includes(row)).map(outputNode),
      ...(scaffolds.length ? [{ id: 'Scaffold snapshots', collapsed: true, label: <>Scaffold snapshots · {scaffolds.length} <span className="experiment-ascii-comment"># Materialized from the Phase 1 plan</span></>, children: scaffolds.map(outputNode) }] : [])
    ];
  };
  const phases = experiment.phases?.length ? experiment.phases.filter(phase => !phaseId || phase.id === phaseId).map(phase => ({ ...phase, rows: rows.filter(row => row.sample.phaseId === phase.id) }))
    : experiment.workflow.stages.map((stage, index) => ({ id: stage.id, name: `Phase ${index + 1} · ${stage.name}`, description: '', rows: rows.filter(row => row.stage.id === stage.id) }));
  const nodes: Node[] = [{ id: 'Inputs', label: <strong>Inputs</strong>, children: [
    { id: 'Input cases', collapsed: true, label: <>AgentContexts · {experiment.cases.length} input cases</>, children: experiment.cases.map(input => ({ id: input.id, label: <>{input.name} {action('inspect', () => inspect(input.name, { ...input, runs: related.filter(run => run.agentContextId === input.agentContextId).map(run => ({ name: run.name, contexts: run.contexts, inputs: run.inputs, canvasInputs: run.canvasInputs })) }))}</> })) },
    { id: 'Conditions', label: <>Conditions · {experiment.conditions.map(condition => condition.name).join(', ')} {action('inspect', () => inspect('Conditions', experiment.conditions))}</> },
    { id: 'Settings', label: <>{[...new Set([...related, ...(experiment.generationReview?.runs ?? [])].map(run => `${run.request.model} / ${run.request.effort} · n=${run.request.passes}`))].join('; ') || 'Generation settings not recorded'} {action('settings', () => inspect('Pinned generation settings', related.map(run => ({ name: run.name, request: run.request }))))}</> }
  ] }, ...phases.map(phase => ({ id: phase.id, label: <><strong>{phase.name}</strong> {progress(phase.rows)}</>, children: [
    ...(phase.description ? [{ id: `${phase.id}-comment`, label: <span className="experiment-ascii-comment"># {phase.description}</span> }] : []),
    { id: `${phase.id}-dependencies`, label: <>Inputs · {phase.rows.some(row => row.run?.historyInput) ? 'pinned batch contexts + preceding canvas state' : [...new Set(phase.rows.flatMap(row => row.stage.dependsOn.map(id => experiment.workflow.stages.find(stage => stage.id === id)?.name ?? id)))].join(', ') || 'experiment inputs'}</> },
    { id: `${phase.id}-outputs`, label: <strong>Outputs · {phase.rows.length}</strong>, children: phase.rows.length ? phaseOutputs(phase.rows) : [{ id: `${phase.id}-empty`, label: <span className="evals-muted">No outputs registered yet.</span> }] }
  ] }))];
  return <section className="experiment-overview" aria-label="Experiment workflow">
    <div className="experiment-ascii-root"><strong>{experiment.workflow.name}</strong> {progress(rows)}</div>
    <ul className="experiment-ascii-tree">{nodes.map((node, index) => <Branch key={node.id} node={node} last={index === nodes.length - 1} />)}</ul>
    {drawer && createPortal(<Drawer title={drawer.title} wide onClose={() => setDrawer(undefined)}>{drawer.content}</Drawer>, document.body)}
  </section>;
}
